
/* ===================== MOBILE NAV ===================== */
function toggleMobileNav(){
  const ham=document.getElementById('nav-ham');
  const drawer=document.getElementById('mobile-drawer');
  ham.classList.toggle('open');
  drawer.classList.toggle('open');
}
// Close drawer on outside click
document.addEventListener('click',function(e){
  const ham=document.getElementById('nav-ham');
  const drawer=document.getElementById('mobile-drawer');
  if(drawer && ham && !drawer.contains(e.target) && !ham.contains(e.target)){
    ham.classList.remove('open');
    drawer.classList.remove('open');
  }
});

/* ===================== CURSOR ===================== */
const $c1=document.getElementById('cur'),
      $c2=document.getElementById('cur-ring');
let mx=0,my=0,lx=0,ly=0;
document.addEventListener('mousemove',e=>{
  mx=e.clientX;my=e.clientY;
  $c1.style.left=mx+'px';$c1.style.top=my+'px';
});
(function loop(){
  lx+=(mx-lx)*.1;ly+=(my-ly)*.1;
  $c2.style.left=Math.round(lx)+'px';$c2.style.top=Math.round(ly)+'px';
  requestAnimationFrame(loop);
})();
document.querySelectorAll('a,button,.pcard,.nav-cta,.btn-primary,.btn-secondary').forEach(el=>{
  el.addEventListener('mouseenter',()=>document.body.classList.add('hov'));
  el.addEventListener('mouseleave',()=>document.body.classList.remove('hov'));
});

/* ===================== LOADER ===================== */
let lp=0;
const $lb=document.getElementById('lbar'),
      $ln=document.getElementById('lpct'),
      $lo=document.getElementById('loader');
const ltimer=setInterval(()=>{
  lp+=Math.random()*22;
  if(lp>=100){lp=100;clearInterval(ltimer);setTimeout(()=>{$lo.classList.add('gone');initCharts();},300);}
  $lb.style.width=lp+'%';
  $ln.textContent=Math.round(lp)+'%';
},80);

/* ===================== NAV SCROLL ===================== */
window.addEventListener('scroll',()=>{
  document.getElementById('mainnav').classList.toggle('pinned',scrollY>30);
},{ passive:true });

/* ===================== SMOOTH SCROLL ===================== */
function scrollTo(id){
  const el=document.getElementById(id);
  if(el)setTimeout(()=>el.scrollIntoView({behavior:'smooth'}),50);
}

/* ===================== REVEAL ===================== */
const ro=new IntersectionObserver(entries=>
  entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('vis');ro.unobserve(e.target);}})
,{threshold:.08});
function attachReveal(){document.querySelectorAll('.rv:not(.vis)').forEach(el=>ro.observe(el));}
attachReveal();

/* ===================== PAGES ===================== */
function showPg(id){
  document.querySelectorAll('.pg').forEach(p=>p.classList.remove('on'));
  document.getElementById(id).classList.add('on');
  window.scrollTo(0,0);
}
function goHome(){
  showPg('pg-home');
  setTimeout(attachReveal,100);
}

/* ===================== PROJECT FILTER ===================== */
function fp(cat,btn){
  document.querySelectorAll('.pf-btn').forEach(b=>b.classList.remove('act'));
  btn.classList.add('act');
  document.querySelectorAll('.pcard').forEach(c=>{
    c.style.display=(cat==='all'||c.dataset.cat?.includes(cat))?'':'none';
  });
}

/* ===================== CHARTS ===================== */
function initCharts(){
  const pie=document.getElementById('pieC');
  const bar=document.getElementById('barC');
  if(!pie||!bar)return;
  new Chart(pie,{
    type:'doughnut',
    data:{
      labels:['Enterprise','Healthcare','Agri-Tech','SaaS','Other'],
      datasets:[{data:[35,25,20,15,5],
        backgroundColor:['#4493f8','#a371f7','#3fb950','#f0883e','#6e7681'],
        borderWidth:2,borderColor:'#141d2b',hoverOffset:6}]
    },
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>' '+c.label+': '+c.parsed+'%'}}},
      cutout:'62%'}
  });
  new Chart(bar,{
    type:'bar',
    data:{
      labels:['Web','Mobile','Tablet'],
      datasets:[{data:[72,48,18],
        backgroundColor:['rgba(68,147,248,.55)','rgba(62,207,207,.45)','rgba(163,113,247,.4)'],
        borderRadius:5,borderSkipped:false}]
    },
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{display:false}},
      scales:{
        x:{grid:{color:'rgba(255,255,255,.03)'},ticks:{color:'#484f58',font:{size:11,family:'Inter'}}},
        y:{grid:{color:'rgba(255,255,255,.03)'},ticks:{color:'#484f58',font:{size:11,family:'Inter'}},max:100,beginAtZero:true}
      }}
  });
}

